"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { DashboardHeader } from "@/components/dashboard-header";
import { DashboardSidebar } from "@/components/dashboard-sidebar";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import {
  Plus,
  Search,
  Eye,
  Pencil,
  Trash2,
  Radio,
  MapPin,
  Battery,
  Wifi,
  Loader2,
  ExternalLink,
} from "lucide-react";
import {
  getAllSensors,
  deleteSensor,
  type Sensor,
  getSensorStats,
} from "@/lib/api/sensors";
import { useToast } from "@/hooks/use-toast";

export default function SensorsPage() {
  const [page, setPage] = useState(1);
  const [limit] = useState(10);
  const [pagination, setPagination] = useState<{
    totalPages: number;
    totalCount: number;
    hasNextPage: boolean;
    hasPrevPage: boolean;
  } | null>(null);

  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [sensors, setSensors] = useState<Sensor[]>([]);
  const [loading, setLoading] = useState(true);
  const [deleting, setDeleting] = useState<string | null>(null);
  const { toast } = useToast();
  const [stats, setStats] = useState<{
    total: number;
    active: number;
    inactive: number;
    warning: number;
  } | null>(null);

  useEffect(() => {
    fetchSensorStats();
  }, []);

  const fetchSensorStats = async () => {
    const response = await getSensorStats();
    if (response.success && response.data) {
      setStats(response.data);
    }
  };

  useEffect(() => {
    fetchSensors();
  }, [page]);

  useEffect(() => {
    setPage(1);
  }, [searchQuery]);

  const fetchSensors = async () => {
    setLoading(true);
    try {
      const response = await getAllSensors({
        include: true,
        page,
        limit,
        search: searchQuery || undefined,
      });

      if (response.success && response.data && response.pagination) {
        setSensors(response.data);
        setPagination(response.pagination);
      } else {
        toast({
          title: "Error",
          description: response.error || "Failed to fetch sensors",
          variant: "destructive",
        });
      }
    } catch {
      toast({
        title: "Error",
        description: "Failed to fetch sensors",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const getStatusBadge = (status: string) => {
    const normalizedStatus = status.toLowerCase();
    switch (normalizedStatus) {
      case "active":
      case "online":
        return (
          <Badge className="bg-emerald-950/80 text-emerald-300 border border-emerald-500/40 text-[11px] font-medium px-2.5 py-0.5 rounded-full">
            Active
          </Badge>
        );
      case "inactive":
      case "offline":
        return (
          <Badge className="bg-red-950/80 text-red-300 border border-red-500/40 text-[11px] font-medium px-2.5 py-0.5 rounded-full">
            Inactive
          </Badge>
        );
      case "warning":
        return (
          <Badge className="bg-amber-950/80 text-amber-300 border border-amber-500/40 text-[11px] font-medium px-2.5 py-0.5 rounded-full">
            Warning
          </Badge>
        );
      default:
        return (
          <Badge variant="secondary" className="bg-slate-800 text-slate-300 text-[11px] px-2.5 py-0.5 rounded-full">
            {status}
          </Badge>
        );
    }
  };

  const handleDelete = async (id: string, sensorName: string) => {
    setDeleting(id);
    try {
      const response = await deleteSensor(id);
      if (response.success) {
        setSensors(sensors.filter((sensor) => sensor.id !== id));
        toast({
          title: "Success",
          description: `Sensor "${sensorName}" deleted successfully`,
        });
      } else {
        toast({
          title: "Error",
          description: response.error || "Failed to delete sensor",
          variant: "destructive",
        });
      }
    } catch (error) {
      toast({
        title: "Error",
        description: "Failed to delete sensor",
        variant: "destructive",
      });
    } finally {
      setDeleting(null);
    }
  };

  // Stats calculations
  const totalSensors = sensors.length;
  const onlineSensors = sensors.filter(
    (s) => s.status.toLowerCase() === "active",
  ).length;
  const warningSensors = sensors.filter(
    (s) => s.status.toLowerCase() === "warning",
  ).length;
  const offlineSensors = sensors.filter(
    (s) => s.status.toLowerCase() === "inactive",
  ).length;

  return (
    <div className="p-4 md:p-6 lg:p-8 min-h-screen">
      <div className="mx-auto max-w-7xl space-y-6">
        {/* Header Banner */}
        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between border-b border-slate-800/80 pb-5">
          <div>
            <div className="flex items-center gap-2 mb-1">
              <Badge className="bg-blue-950/80 text-blue-400 border border-blue-500/40 text-[10px] font-mono uppercase tracking-wider">
                TACTICAL NETWORK
              </Badge>
            </div>
            <h1 className="text-2xl font-extrabold text-white md:text-3xl tracking-tight">
              Sensor Node Management
            </h1>
            <p className="mt-1 text-xs md:text-sm text-slate-400">
              Real-time monitoring and configuration of ground sensors, cameras, and IoT nodes
            </p>
          </div>
          <Link href="/sensors/add">
            <Button className="gap-2 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 text-white font-semibold text-xs py-2.5 px-4 rounded-xl shadow-lg shadow-blue-950/50 border border-blue-400/30 transition-all hover:cursor-pointer">
              <Plus className="h-4 w-4" />
              Add Sensor
            </Button>
          </Link>
        </div>

        {/* Stats Cards Grid */}
        <div className="grid gap-4 sm:grid-cols-3">
          <Card className="border border-slate-800 bg-slate-900/80 backdrop-blur-sm rounded-2xl shadow-md">
            <CardContent className="flex items-center gap-4 p-4">
              <div className="flex h-12 w-12 items-center justify-center rounded-xl bg-blue-950/80 text-blue-400 border border-blue-500/30">
                <Radio className="h-6 w-6" />
              </div>
              <div>
                <p className="text-xs font-semibold uppercase tracking-wider text-slate-400">Total Sensors</p>
                <p className="text-2xl font-extrabold text-white font-mono mt-0.5">
                  {stats?.total ?? totalSensors}
                </p>
              </div>
            </CardContent>
          </Card>
          <Card className="border border-slate-800 bg-slate-900/80 backdrop-blur-sm rounded-2xl shadow-md">
            <CardContent className="flex items-center gap-4 p-4">
              <div className="flex h-12 w-12 items-center justify-center rounded-xl bg-emerald-950/80 text-emerald-400 border border-emerald-500/30">
                <Wifi className="h-6 w-6" />
              </div>
              <div>
                <p className="text-xs font-semibold uppercase tracking-wider text-slate-400">Active Nodes</p>
                <p className="text-2xl font-extrabold text-emerald-400 font-mono mt-0.5">
                  {stats?.active ?? onlineSensors}
                </p>
              </div>
            </CardContent>
          </Card>
          <Card className="border border-slate-800 bg-slate-900/80 backdrop-blur-sm rounded-2xl shadow-md">
            <CardContent className="flex items-center gap-4 p-4">
              <div className="flex h-12 w-12 items-center justify-center rounded-xl bg-red-950/80 text-red-400 border border-red-500/30">
                <MapPin className="h-6 w-6" />
              </div>
              <div>
                <p className="text-xs font-semibold uppercase tracking-wider text-slate-400">Inactive Nodes</p>
                <p className="text-2xl font-extrabold text-red-400 font-mono mt-0.5">
                  {stats?.inactive ?? offlineSensors}
                </p>
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Search Bar */}
        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between bg-slate-900/60 p-4 rounded-2xl border border-slate-800/80 backdrop-blur-sm">
          <div className="relative flex-1 sm:max-w-md">
            <Search className="absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
            <Input
              placeholder="Search sensors by name, ID, type..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter") {
                  e.preventDefault();
                  setPage(1);
                  fetchSensors();
                }
              }}
              className="border-slate-700/80 bg-slate-950 pl-10 text-slate-100 placeholder:text-slate-500 focus:border-blue-500 focus:ring-blue-500/20 rounded-xl text-xs"
            />
          </div>
          <div className="flex items-center gap-2">
            <span className="text-xs font-medium text-slate-400">
              Showing <span className="text-slate-200 font-bold">{sensors.length}</span> of{" "}
              <span className="text-slate-200 font-bold">{pagination?.totalCount ?? 0}</span> sensors
            </span>
          </div>
        </div>

        {/* Loading State */}
        {loading && (
          <div className="flex flex-col items-center justify-center rounded-2xl border border-slate-800 bg-slate-900/50 py-16 backdrop-blur-sm">
            <Loader2 className="mb-4 h-10 w-10 animate-spin text-blue-500" />
            <p className="text-sm font-medium text-slate-400">
              Scanning sensor nodes...
            </p>
          </div>
        )}

        {/* Desktop Table */}
        {!loading && (
          <div className="hidden rounded-2xl border border-slate-800 bg-slate-900/70 backdrop-blur-sm lg:block overflow-hidden shadow-xl">
            <Table>
              <TableHeader>
                <TableRow className="border-slate-800 bg-slate-950/80 hover:bg-transparent">
                  <TableHead className="text-slate-400 font-semibold text-xs uppercase tracking-wider">Sensor ID</TableHead>
                  <TableHead className="text-slate-400 font-semibold text-xs uppercase tracking-wider">Name</TableHead>
                  <TableHead className="text-slate-400 font-semibold text-xs uppercase tracking-wider">Area</TableHead>
                  <TableHead className="text-slate-400 font-semibold text-xs uppercase tracking-wider">Type</TableHead>
                  <TableHead className="text-slate-400 font-semibold text-xs uppercase tracking-wider">Latitude</TableHead>
                  <TableHead className="text-slate-400 font-semibold text-xs uppercase tracking-wider">Longitude</TableHead>
                  <TableHead className="text-slate-400 font-semibold text-xs uppercase tracking-wider">IP Address</TableHead>
                  <TableHead className="text-slate-400 font-semibold text-xs uppercase tracking-wider">Added By</TableHead>
                  <TableHead className="text-slate-400 font-semibold text-xs uppercase tracking-wider">Status</TableHead>
                  <TableHead className="text-right text-slate-400 font-semibold text-xs uppercase tracking-wider">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {sensors.map((sensor) => (
                  <TableRow
                    key={sensor.id}
                    className="border-slate-800/60 hover:bg-slate-800/50 transition-colors"
                  >
                    <TableCell className="font-mono text-xs font-semibold text-blue-400">
                      {sensor.sensorId}
                    </TableCell>
                    <TableCell className="font-medium text-slate-100 text-sm">{sensor.name}</TableCell>
                    <TableCell className="text-xs text-slate-300 font-medium">
                      {sensor.area?.name || "Unassigned"}
                    </TableCell>
                    <TableCell className="text-xs text-slate-400">
                      {sensor.sensorType}
                    </TableCell>
                    <TableCell className="font-mono text-xs text-slate-400">
                      {typeof sensor.latitude === "number" ? sensor.latitude.toFixed(4) : (sensor.latitude || "N/A")}
                    </TableCell>
                    <TableCell className="font-mono text-xs text-slate-400">
                      {typeof sensor.longitude === "number" ? sensor.longitude.toFixed(4) : (sensor.longitude || "N/A")}
                    </TableCell>
                    <TableCell className="font-mono text-xs text-slate-300">
                      {sensor.ipAddress || "N/A"}
                    </TableCell>
                    <TableCell>
                      <Badge className="bg-amber-950/80 text-amber-300 border border-amber-500/40 text-[11px] font-medium px-2 py-0.5 rounded-full">
                        {sensor.addedBy || "N/A"}
                      </Badge>
                    </TableCell>
                    <TableCell>{getStatusBadge(sensor.status)}</TableCell>
                    <TableCell className="text-right">
                      <div className="flex items-center justify-end gap-1.5">
                        <Link href={`/sensors/${sensor.id}`}>
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-8 w-8 text-slate-400 hover:bg-slate-800 hover:text-white rounded-lg transition-all"
                            title="View Sensor"
                          >
                            <Eye className="h-4 w-4" />
                          </Button>
                        </Link>
                        <Link href={`/sensors/${sensor.id}/edit`}>
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-8 w-8 text-slate-400 hover:bg-slate-800 hover:text-white rounded-lg transition-all"
                            title="Edit Sensor"
                          >
                            <Pencil className="h-4 w-4" />
                          </Button>
                        </Link>
                        <AlertDialog>
                          <AlertDialogTrigger asChild>
                            <Button
                              variant="ghost"
                              size="icon"
                              className="h-8 w-8 text-slate-400 hover:bg-red-950/50 hover:text-red-400 rounded-lg transition-all"
                              disabled={deleting === sensor.id}
                              title="Delete Sensor"
                            >
                              {deleting === sensor.id ? (
                                <Loader2 className="h-4 w-4 animate-spin" />
                              ) : (
                                <Trash2 className="h-4 w-4" />
                              )}
                            </Button>
                          </AlertDialogTrigger>
                          <AlertDialogContent className="border-slate-800 bg-[#0f172a] rounded-2xl shadow-2xl">
                            <AlertDialogHeader>
                              <AlertDialogTitle className="text-white font-bold">
                                Delete Sensor
                              </AlertDialogTitle>
                              <AlertDialogDescription className="text-slate-400 text-xs">
                                Are you sure you want to delete "{sensor.name}"? This action cannot be undone.
                              </AlertDialogDescription>
                            </AlertDialogHeader>
                            <AlertDialogFooter>
                              <AlertDialogCancel className="border-slate-700 bg-slate-800/40 text-slate-300 hover:bg-slate-800 rounded-lg">
                                Cancel
                              </AlertDialogCancel>
                              <AlertDialogAction
                                onClick={() =>
                                  handleDelete(sensor.id, sensor.name)
                                }
                                className="bg-red-600 text-white hover:bg-red-500 rounded-lg font-semibold"
                              >
                                Delete
                              </AlertDialogAction>
                            </AlertDialogFooter>
                          </AlertDialogContent>
                        </AlertDialog>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        )}

        {/* Mobile Cards */}
        {!loading && (
          <div className="grid gap-4 lg:hidden">
            {sensors.map((sensor) => (
              <Card key={sensor.id} className="border-slate-800 bg-slate-900/80 rounded-xl shadow-md">
                <CardContent className="p-4 space-y-3">
                  <div className="flex items-start justify-between">
                    <div>
                      <p className="font-mono text-xs text-blue-400">
                        {sensor.sensorId}
                      </p>
                      <h3 className="text-base font-semibold text-slate-100">
                        {sensor.name}
                      </h3>
                    </div>
                    {getStatusBadge(sensor.status)}
                  </div>
                  <div className="grid grid-cols-2 gap-2 text-xs pt-1 border-t border-slate-800">
                    <div>
                      <span className="text-slate-400">Area: </span>
                      <span className="text-slate-200 font-medium">
                        {sensor.area?.name || "Unassigned"}
                      </span>
                    </div>
                    <div>
                      <span className="text-slate-400">Type: </span>
                      <span className="text-slate-200">{sensor.sensorType}</span>
                    </div>
                    <div>
                      <span className="text-slate-400">IP: </span>
                      <span className="font-mono text-slate-300">
                        {sensor.ipAddress || "N/A"}
                      </span>
                    </div>
                  </div>
                  <div className="flex gap-2 pt-2 border-t border-slate-800">
                    <Link href={`/sensors/${sensor.id}`} className="flex-1">
                      <Button
                        variant="outline"
                        className="w-full gap-2 border-slate-700 bg-slate-800/40 text-slate-200 hover:bg-slate-800 rounded-lg text-xs"
                      >
                        <Eye className="h-3.5 w-3.5" /> View
                      </Button>
                    </Link>
                    <Link
                      href={`/sensors/${sensor.id}/edit`}
                      className="flex-1"
                    >
                      <Button
                        variant="outline"
                        className="w-full gap-2 border-slate-700 bg-slate-800/40 text-slate-200 hover:bg-slate-800 rounded-lg text-xs"
                      >
                        <Pencil className="h-3.5 w-3.5" /> Edit
                      </Button>
                    </Link>
                    <AlertDialog>
                      <AlertDialogTrigger asChild>
                        <Button
                          variant="outline"
                          size="icon"
                          className="border-slate-700 bg-red-950/20 text-red-400 hover:bg-red-950/40 rounded-lg text-xs"
                          disabled={deleting === sensor.id}
                        >
                          {deleting === sensor.id ? (
                            <Loader2 className="h-3.5 w-3.5 animate-spin" />
                          ) : (
                            <Trash2 className="h-3.5 w-3.5" />
                          )}
                        </Button>
                      </AlertDialogTrigger>
                      <AlertDialogContent className="border-slate-800 bg-[#0f172a] rounded-2xl shadow-2xl">
                        <AlertDialogHeader>
                          <AlertDialogTitle className="text-white font-bold">
                            Delete Sensor
                          </AlertDialogTitle>
                          <AlertDialogDescription className="text-slate-400 text-xs">
                            Are you sure you want to delete "{sensor.name}"? This action cannot be undone.
                          </AlertDialogDescription>
                        </AlertDialogHeader>
                        <AlertDialogFooter>
                          <AlertDialogCancel className="border-slate-700 bg-slate-800/40 text-slate-300 hover:bg-slate-800 rounded-lg">
                            Cancel
                          </AlertDialogCancel>
                          <AlertDialogAction
                            onClick={() => handleDelete(sensor.id, sensor.name)}
                            className="bg-red-600 text-white hover:bg-red-500 rounded-lg font-semibold"
                          >
                            Delete
                          </AlertDialogAction>
                        </AlertDialogFooter>
                      </AlertDialogContent>
                    </AlertDialog>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        )}

        {!loading && sensors.length === 0 && (
          <div className="flex flex-col items-center justify-center rounded-2xl border border-slate-800 bg-slate-900/50 py-16">
            <Radio className="mb-4 h-12 w-12 text-slate-600" />
            <p className="text-base font-semibold text-slate-300">No sensor nodes found</p>
            <p className="text-xs text-slate-500 mt-1">
              Try adjusting your search query or add a new sensor node
            </p>
            <Link href="/sensors/add" className="mt-4">
              <Button className="gap-2 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 text-white font-semibold text-xs py-2 px-4 rounded-xl shadow-md">
                <Plus className="h-4 w-4" /> Add First Sensor
              </Button>
            </Link>
          </div>
        )}

        {!loading && pagination && pagination.totalPages > 1 && (
          <div className="flex items-center justify-between pt-2">
            <Button
              variant="outline"
              disabled={!pagination.hasPrevPage}
              onClick={() => setPage((p) => Math.max(1, p - 1))}
              className="border-slate-700 bg-slate-900/80 text-xs text-slate-200 hover:bg-slate-800 rounded-lg"
            >
              Previous
            </Button>

            <p className="text-xs font-mono text-slate-400">
              Page <span className="text-slate-200 font-bold">{page}</span> of{" "}
              <span className="text-slate-200 font-bold">{pagination.totalPages}</span>
            </p>

            <Button
              variant="outline"
              disabled={!pagination.hasNextPage}
              onClick={() => setPage((p) => p + 1)}
              className="border-slate-700 bg-slate-900/80 text-xs text-slate-200 hover:bg-slate-800 rounded-lg"
            >
              Next
            </Button>
          </div>
        )}
      </div>
    </div>
  );
}
